// Import of required libraries
import { test, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import { expect } from '@playwright/test';
import { setProjectName, openSaveToDialog } from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(89000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(baseUrl);
    await setProjectName(page, '');
    await page.goto(`${baseUrl}/`);
    await openSaveToDialog(page);

    // An empty name hits the !projectName branch of the guard - the same branch an
    // embedder falls into when the scene name arrives via the name prop instead of
    // appState.name (JSONExportDialog.tsx reads appState.name directly, line 51).
    await expect(page.getByRole('button', { name: 'Save to file' })).toBeDisabled();
    await expect(page.getByRole('button', { name: 'Export to Link' })).toBeEnabled();
    await expect(page.getByRole('heading', { name: 'Save to disk' })).toBeVisible();
});
